ee:message.ee:set-payload:
%dw 2.0
output application/csv 
---
payload map (item) -> 
	if (item.id == vars.productId) 
   		item update {
            case .stock -> (item.stock default 0) + 1
        }
    else item

logger.message:
#[%dw 2.0
output application/json
---
{
  "step": "increment stock",
  "data": {
    "business": {
      "message": "add stock for product: " ++ (vars.productId default ""),
      "status": "success"
    },
    "technical": {
      "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
    }
  }
}]

